templates.template:
// CloudCheats Profile Layout v4

.cc-profile-wrap { max-width: 100%; }

// ── Header / Cover ────────────────────────────────────────────────────────────

.cc-profile-cover {
    position: relative;
    border-radius: 6px;
    overflow: hidden;
}

.cc-banner-bg {
    position: relative;
    min-height: 195px;
    background: linear-gradient(135deg, hsl(230, 38%, 12%) 0%, hsl(222, 30%, 14%) 60%, hsl(215, 45%, 17%) 100%);
    display: block;
}

.cc-banner-bg::after {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(to bottom, transparent 25%, rgba(0,0,0,.7) 100%);
    pointer-events: none;
}

.cc-profile-header {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: flex-end;
    gap: 16px;
    padding: 0 20px 18px;
    flex-wrap: wrap;
}

// ── Avatar gradient ring ──────────────────────────────────────────────────────

.cc-avatar-ring {
    flex-shrink: 0;
    margin-bottom: -16px;
    padding: 3px;
    border-radius: 12px;
    background: linear-gradient(135deg, rgba(80,100,255,.9) 0%, rgba(160,60,255,.9) 100%);
    display: inline-block;
}

.cc-avatar-ring .avatarWrapper { display: block; }

.cc-avatar-ring .avatar {
    width: 120px !important;
    height: 120px !important;
    border-radius: 8px !important;
    border: none !important;
    display: block;
}

.cc-avatar-ring .avatar--image {
    width: 120px;
    height: 120px;
    object-fit: cover;
    border-radius: 8px;
}

// ── Header info ───────────────────────────────────────────────────────────────

.cc-header-info {
    flex: 1;
    min-width: 180px;
    padding-bottom: 4px;
}

.cc-username {
    font-size: 1.6em;
    font-weight: 700;
    color: #fff;
    text-shadow: 0 1px 4px rgba(0,0,0,.6);
    margin: 0 0 5px;
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}

.cc-username .username, .cc-username a { color: inherit !important; text-shadow: inherit; }

.cc-username-history-trigger { opacity: .6; font-size: .7em; }

.cc-header-blurb {
    color: rgba(255,255,255,.7);
    font-size: 0.88em;
}

.cc-header-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    align-items: flex-end;
    padding-bottom: 4px;
    margin-left: auto;
}

.cc-staff-tools { display: flex; flex-wrap: wrap; gap: 6px; }

// ── 3-column body ─────────────────────────────────────────────────────────────

.cc-profile-body {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 12px 0 0;
}

@media (max-width: 768px) {
    .cc-profile-body { flex-direction: column; }
    .cc-profile-sidebar, .cc-profile-right { width: 100% !important; }
}

// ── Left sidebar ──────────────────────────────────────────────────────────────

.cc-profile-sidebar {
    width: 225px;
    flex-shrink: 0;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.cc-sidebar-card {
    background: @xf-contentBg;
    border: 1px solid @xf-borderColor;
    border-radius: 6px;
}

// Online/Offline status
.cc-status-card { padding: 14px 16px; }

.cc-status-main {
    display: flex;
    align-items: center;
    gap: 9px;
}

.cc-status-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    flex-shrink: 0;
}

.cc-status-label {
    font-size: 1.1em;
    font-weight: 800;
    letter-spacing: 0.12rem;
    text-transform: uppercase;
}

.cc-status-sub {
    font-size: 0.78em;
    color: @xf-textColorMuted;
    margin-top: 5px;
    line-height: 1.4;
}

.cc-status--online .cc-status-dot { background: #55e180; box-shadow: 0 0 7px rgba(85,225,128,.7); }
.cc-status--online .cc-status-label { color: #55e180; }
.cc-status--offline .cc-status-dot { background: @xf-textColorMuted; }
.cc-status--offline .cc-status-label { color: @xf-textColorMuted; }

// Rep / Points blocks (vacban statusblock style)
.cc-rep-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 6px;
}

.cc-rep-block {
    background: @xf-contentBg;
    border: 1px solid @xf-borderColor;
    border-radius: 6px;
    padding: 12px 10px 10px;
    text-align: center;
    position: relative;
}

.cc-rep-num {
    font-size: 1.3em;
    font-weight: 700;
    line-height: 1;
    margin-bottom: 4px;
}

.cc-rep-label {
    font-size: 0.7em;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: @xf-textColorMuted;
    margin-bottom: 6px;
}

.cc-rep-icon {
    font-size: 0.8em;
    color: @xf-textColorMuted;
}

// Info rows
.cc-info-card { padding: 8px 14px; }

.cc-info-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 6px;
    padding: 6px 0;
    border-bottom: 1px solid @xf-borderColor;
    font-size: 0.81em;
}

.cc-info-row:last-child { border-bottom: none; }

.cc-info-label {
    color: @xf-textColorMuted;
    font-weight: 600;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    gap: 5px;
}

.cc-info-val {
    text-align: right;
    word-break: break-word;
    color: @xf-textColor;
}

// ── Center content ────────────────────────────────────────────────────────────

.cc-profile-content {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

// Stats card — horizontal grid 4 per row like vacban
.cc-stats-card {
    background: @xf-contentBg;
    border: 1px solid @xf-borderColor;
    border-radius: 6px;
    overflow: hidden;
}

.cc-stats-hgrid .pairJustifier {
    display: flex;
    flex-wrap: wrap;
    margin: 0;
}

.cc-stats-hgrid dl.pairs {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    flex: 1 1 22%;
    min-width: 80px;
    padding: 14px 8px;
    border-right: 1px solid @xf-borderColor;
    border-bottom: 1px solid @xf-borderColor;
    margin: 0;
}

.cc-stats-hgrid dl.pairs:last-child { border-right: none; }

.cc-stats-hgrid dl.pairs dd {
    font-size: 1.25em;
    font-weight: 700;
    margin: 0 0 3px;
    order: -1;
}

.cc-stats-hgrid dl.pairs dd a {
    color: inherit;
    font-size: inherit;
    font-weight: inherit;
    text-decoration: none;
}

.cc-stats-hgrid dl.pairs dt {
    font-size: 0.68em;
    text-transform: uppercase;
    letter-spacing: .05em;
    color: @xf-textColorMuted;
}

// User banners strip (horizontal in center)
.cc-banners-strip {
    background: @xf-contentBg;
    border: 1px solid @xf-borderColor;
    border-radius: 6px;
    padding: 12px 14px;
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    align-items: center;
    justify-content: center;
}

.cc-banners-strip .userBanners { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; }
.cc-banners-strip .userBanner { flex: 0 0 auto; }

// ── Profile tabs block (vacban exact CSS) ─────────────────────────────────────

.profile-tabs-block {
    background: @xf-contentBg;
    border-radius: .5rem;
    overflow: hidden;
    margin-bottom: 0;
    border: 1px solid @xf-borderColor;
}

.profile-tabs-bar {
    display: flex;
    gap: 6px;
    padding: 10px 10px 0 10px;
    background: @xf-contentBg;
    border-bottom: 1px solid @xf-borderColor;
}

.profile-tab {
    flex: 1;
    appearance: none;
    -webkit-appearance: none;
    background: transparent;
    border: 1px solid transparent;
    color: @xf-textColorMuted;
    font: inherit;
    font-size: 14px;
    font-weight: 600;
    padding: 11px 18px;
    border-radius: 10px 10px 0 0;
    cursor: pointer;
    transition: color .18s ease, background .18s ease, border-color .18s ease;
    text-align: center;
    user-select: none;
}

.profile-tab:hover { color: @xf-textColor; }

.profile-tab.is-active {
    background: @xf-contentBg;
    color: @xf-textColor;
    border-color: @xf-borderColor;
    border-bottom-color: transparent;
}

.profile-tabs-content {
    border-radius: 0 0 .35rem .35rem;
    text-align: center;
    min-height: 80px;
    padding: 18px;
}

.profile-tab-panel { display: none; text-align: center; }
.profile-tab-panel > .profile-tab-panel-inner { display: inline-block; margin: 1px; max-width: 100%; text-align: left; }
.profile-tab-panel.is-active { display: block; }
.profile-tab-panel.is-entering { animation: profileTabFade .24s ease both; }

@keyframes profileTabFade {
    from { opacity: 0; transform: translateY(4px); }
    to   { opacity: 1; transform: translateY(0); }
}

.profile-tab-empty {
    color: @xf-textColorMuted;
    font-style: italic;
    font-size: 13px;
}

// Main tab bar
.cc-profile-content .block-tabHeader.tabs {
    margin-bottom: 0;
    border-radius: 6px 6px 0 0;
}

.cc-profile-content .block { border-radius: 0 0 6px 6px; margin-top: 0; }

.cc-profile-content .tabPanes { margin: 0; padding: 0; list-style: none; }

// ── Right sidebar ─────────────────────────────────────────────────────────────

.cc-profile-right {
    width: 190px;
    flex-shrink: 0;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

// YOS badge in right sidebar
.cc-yos-sidebar-card { padding: 12px 14px; }

.cc-yos-sidebar-card .dp-service-badge-profile {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 9px 14px;
    border-radius: 20px;
    font-size: 0.85em;
    font-weight: 700;
    justify-content: center;
}

.cc-yos-sidebar-card .dp-service-badge-icon { flex-shrink: 0; width: 27px; }
.cc-yos-sidebar-card .dp-service-badge-icon svg { display: block; }
.cc-yos-sidebar-card .dp-service-badge-duration { font-size: 1.25em; font-weight: 800; }
.cc-yos-sidebar-card .dp-service-badge-title { font-size: 0.78em; opacity: .85; }

.cc-yos-sidebar-card.year-1  .dp-service-badge-profile { background: rgba(180,140,100,.15); color: #b48c64; border: 1px solid #b48c64; }
.cc-yos-sidebar-card.year-2  .dp-service-badge-profile { background: rgba(160,160,170,.15); color: #a0a0aa; border: 1px solid #a0a0aa; }
.cc-yos-sidebar-card.year-3  .dp-service-badge-profile { background: rgba(255,215,  0,.15); color: #ffd700; border: 1px solid #ffd700; }
.cc-yos-sidebar-card.year-4  .dp-service-badge-profile { background: rgba(180,235,255,.15); color: #b4ebff; border: 1px solid #b4ebff; }
.cc-yos-sidebar-card.year-5  .dp-service-badge-profile { background: rgba(255,165,  0,.15); color: #ffa500; border: 1px solid #ffa500; }
.cc-yos-sidebar-card.year-6  .dp-service-badge-profile { background: rgba(160,200,255,.15); color: #a0c8ff; border: 1px solid #a0c8ff; }
.cc-yos-sidebar-card.year-7  .dp-service-badge-profile { background: rgba(220,160,255,.15); color: #dca0ff; border: 1px solid #dca0ff; }
.cc-yos-sidebar-card.year-8  .dp-service-badge-profile { background: rgba(255,100,100,.15); color: #ff6464; border: 1px solid #ff6464; }
.cc-yos-sidebar-card.year-9  .dp-service-badge-profile { background: rgba( 80,200,120,.15); color: #50c878; border: 1px solid #50c878; }
.cc-yos-sidebar-card.year-10 .dp-service-badge-profile { background: rgba(255,215,  0,.20); color: #ffd700; border: 2px solid #ffd700; box-shadow: 0 0 12px rgba(255,215,0,.4); }
// ── v5: Banned stamp overlay on profile avatar ────────────────────────────────

.cc-avatar-ring { position: relative; }

.cc-avatar-ring--banned .avatarWrapper { position: relative; }

.cc-avatar-ring--banned .avatarWrapper::after {
    content: 'BANNED';
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) rotate(-12deg);
    font-family: Impact, Arial Black, sans-serif;
    font-size: 22px;
    font-weight: 900;
    color: rgba(215, 15, 15, 0.93);
    border: 3px solid rgba(215, 15, 15, 0.88);
    padding: 4px 9px;
    border-radius: 3px;
    pointer-events: none;
    z-index: 5;
    white-space: nowrap;
    letter-spacing: 0.06em;
    background: rgba(0,0,0,0.18);
    text-shadow: 1px 1px 3px rgba(0,0,0,0.5);
}

// ── v5: Staff Tools button (red filled) ──────────────────────────────────────

.cc-staff-tools-btn {
    background: #c40f20 !important;
    color: #fff !important;
    border-color: #c40f20 !important;
    font-weight: 700;
    border-radius: 6px;
    padding: 6px 14px;
}

.cc-staff-tools-btn:hover {
    background: #a50d1b !important;
    border-color: #a50d1b !important;
    color: #fff !important;
}

// ── v5: Dark-themed ban info block ───────────────────────────────────────────

.cc-profile-wrap .blockMessage--error,
.p-body-pageContent .blockMessage--error {
    background: rgba(180, 10, 10, 0.1);
    border: 1px solid rgba(200, 20, 20, 0.35);
    border-radius: 6px;
    color: @xf-textColor;
}

.cc-profile-wrap .blockMessage--error strong {
    color: #ff6060;
}

.cc-profile-wrap .blockMessage--error a {
    color: #ff9090;
}

.cc-profile-wrap .blockMessage--error .fa--xf {
    color: #ff6060;
}
